-- The 7 tournament schools closest to each 2027 bracket school (Pete, Nov 25 2026:
-- "7 closest schools to each home school"). Source: Pete's sheet, saved as
-- data/bracket/seven-closest-tournament-schools-2027.csv. Stored once; the Daily
-- Digest's scoreboard shows the fan's home school's game, then these schools'
-- games, nearest first. Read-only for the site and the newsletter.
CREATE TABLE IF NOT EXISTS public.school_nearest_schools (
  season_key text NOT NULL,
  home_hsid integer NOT NULL,
  rank smallint NOT NULL CHECK (rank BETWEEN 1 AND 7),
  neighbor_hsid integer NOT NULL,
  miles numeric(7,2) NOT NULL,
  PRIMARY KEY (season_key, home_hsid, rank),
  UNIQUE (season_key, home_hsid, neighbor_hsid),
  CHECK (neighbor_hsid <> home_hsid)
);
GRANT SELECT ON public.school_nearest_schools TO authenticator;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'yatstats_tribune_app') THEN
    GRANT SELECT ON public.school_nearest_schools TO yatstats_tribune_app;
  END IF;
END $$;
ON CONFLICT (season_key, home_hsid, rank) DO NOTHING;
